// Every new square revealed by deleting one noncorner from a catalogue 27-core. Before deletion the footprints must intersect at exactly the deleted vertex. For illegal exteriors enumerate ALL blue fives and test exact patch criterion. CSV: row,diagonal indices as endpoints,deleted,number of quintuples,patch corner pairs,fully blocked quintuple count.
use std::io::{self,BufRead};fn fives(a:&[u32],mut p:u32,q:u32,k:u32,out:&mut Vec<u32>){if k==0{out.push(q);return}while p.count_ones()>=k{let i=p.trailing_zeros()as usize;let bit=1<<i;p^=bit;fives(a,p&!a[i],q|bit,k-1,out)}}fn main(){let mut count=0u64;let mut ext=0u64;let mut graphs=0;for(row,l)in io::stdin().lock().lines().enumerate(){let s=l.unwrap();let b=s.as_bytes();assert_eq!(b[0],90);graphs+=1;let mut a=[0u32;27];let mut e=vec![];let mut h=0;for j in 0..27{for i in 0..j{if (b[1+h/6]-63)>>(5-h%6)&1!=0{a[i]|=1<<j;a[j]|=1<<i;e.push((i,j))}h+=1}}let bs:Vec<_>=e.iter().map(|&(i,j)|a[i]|a[j]).collect();for(i,&v)in bs.iter().enumerate(){for(j,&w)in bs[..i].iter().enumerate(){let d=v&w;if d.count_ones()!=1{continue}let (s,t)=e[i];let (x,y)=e[j];if s==x||s==y||t==x||t==y{continue}let cs=[s,t,x,y];if cs.iter().any(|&c|d>>c&1!=0){continue}count+=1;let u=((1<<27)-1)&!(v|w);if u.count_ones()<5{continue}ext+=1;let mut qs=vec![];fives(&a,u,0,5,&mut qs);if qs.is_empty(){continue}let common=qs.iter().fold(u,|v,&q|v&q);let mut available=0;let mut patches=0;for z in 0..27{if u>>z&1==0{continue}let n=cs.iter().filter(|&&c|a[c]&a[z]&!d==0).count();if n>0{available|=1<<z}if common>>z&1!=0{patches+=n}}let blocked=qs.iter().filter(|&&q|q&available==0).count();println!("{row},{s},{t},{x},{y},{},{},{patches},{blocked}",d.trailing_zeros(),qs.len())}}}eprintln!("graphs {graphs} new squares {count} exterior_ge5 {ext}")}
